import ast
from IR import ir
def make_module(spec, name):
    module = ir.Module(name)
    spec.modules.append(module)
    return module                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                

def make_instance(module, name, type):
    instance = ir.Instance(name, type)
    module.instances.append(instance)
    return instance

def make_spec(name):
    spec = ir.Spec(name)
    return spec